/**
 * Lookup over the published per-endpoint rate limits in
 * rate-limits.generated.js (regenerated by `npm run sync:xapi`).
 *
 *   rateLimitsFor('GET', '/2/tweets/{id}')
 *   // [{ scope: 'app', requests: 450, windowSeconds: 900 }, { scope: 'user', requests: 900, windowSeconds: 900 }]
 *
 * Path parameter names do not have to match: `/2/users/{id}/followers` and
 * `/2/users/:user_id/followers` resolve to the same entry. The live
 * x-rate-limit-* headers on each response always win over these numbers.
 *
 * @module xactions/xapi/rate-limits
 */

import { RATE_LIMIT_ROWS, RATE_LIMITS_SOURCE } from './rate-limits.generated.js';

const shape = (method, routePath) =>
  `${String(method).toUpperCase()} ${String(routePath).replace(/:([A-Za-z_]+)/g, '{$1}').replace(/\{[^}]+\}/g, '{}')}`;

/**
 * Every published entry, expanded.
 * @type {ReadonlyArray<{method: string, path: string, limits: ReadonlyArray<{scope: 'app'|'user', requests: number, windowSeconds: number}>}>}
 */
export const RATE_LIMITS = Object.freeze(
  RATE_LIMIT_ROWS.map(([route, limits]) => {
    const space = route.indexOf(' ');
    return Object.freeze({
      method: route.slice(0, space),
      path: route.slice(space + 1),
      limits: Object.freeze(limits.map(([scope, requests, windowSeconds]) => Object.freeze({ scope, requests, windowSeconds }))),
    });
  }),
);

const INDEX = new Map(RATE_LIMITS.map((entry) => [shape(entry.method, entry.path), entry.limits]));

/**
 * Published limits for one route, or an empty list when X does not publish one.
 * @param {string} method
 * @param {string} routePath
 * @returns {ReadonlyArray<{scope: 'app'|'user', requests: number, windowSeconds: number}>}
 */
export function rateLimitsFor(method, routePath) {
  return INDEX.get(shape(method, routePath)) ?? [];
}

export { RATE_LIMITS_SOURCE };
